<?php
require __DIR__.'/_init.php';require_admin();$statuses=['submitted','in_review','in_progress','completed','declined'];$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$new=is_string($_POST['status']??null)?$_POST['status']:'';if(!in_array($new,$statuses,true))$err='Invalid status.';else{try{if(!update_request_status(db(),$id,(int)$_SESSION['user']['id'],$new))$err='Request not found.';else{flash('Request status updated.');header('Location: /admin.php');exit;}}catch(Throwable $ex){error_log((string)$ex);$err='Status update failed. Please try again.';}}}
$filter=$_GET['status']??'';$search=trim($_GET['q']??'');$where=[];$params=[];if(in_array($filter,$statuses,true)){$where[]='r.status=?';$params[]=$filter;}if($search!==''){$where[]='(r.tracking_id LIKE ? OR r.title LIKE ? OR u.username LIKE ? OR u.full_name LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like,$like);}$sql='SELECT r.*,u.full_name,u.username FROM service_requests r JOIN users u ON u.id=r.user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY r.created_at DESC';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();page_start('Request administration');?>
<div class="eyebrow">CAMPUSFLOW ADMIN</div><h1>Request queue</h1><?php if($err)echo '<p class="error">'.e($err).'</p>';?><form method="get" class="filters"><label>Search<input name="q" value="<?=e($search)?>" placeholder="Student, title or tracking ID"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach($statuses as $status):?><option value="<?=e($status)?>" <?=$filter===$status?'selected':''?>><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach;?></select></label><button class="button small">Filter</button></form><div class="table-wrap"><table><tr><th>Student</th><th>Request</th><th>Tracking</th><th>Status</th><th>Update</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><small>@<?=e($r['username'])?></small></td><td><?=e($r['title'])?><small><?=e($r['category'])?></small></td><td><?=e($r['tracking_id'])?></td><td><?=e($r['status'])?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach($statuses as $s)echo '<option'.($s===$r['status']?' selected':'').'>'.e($s).'</option>';?></select><button class="button small">Save</button></form></td></tr><?php endforeach;?></table></div><?php page_end();?>
